import {
  isGeneratedDirectionLabel,
  type GeneratedDirectionLabel,
} from "~/domain/surface/direction";
import type { TranslationKey } from "~/i18n/en";

const DIRECTION_TRANSLATION_KEYS = {
  northbound: "Northbound",
  southbound: "Southbound",
  eastbound: "Eastbound",
  westbound: "Westbound",
  outbound: "Outbound",
  inbound: "Inbound",
} satisfies Record<GeneratedDirectionLabel, TranslationKey>;

/** Translate only labels explicitly marked as generated by Core. */
export function presentDirectionLabel(
  label: string,
  generatedLabel: GeneratedDirectionLabel | undefined,
  t: (key: TranslationKey) => string,
): string {
  return isGeneratedDirectionLabel(generatedLabel)
    ? t(DIRECTION_TRANSLATION_KEYS[generatedLabel])
    : label;
}
